  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/vendors/%7Bvendor_id%7D/insurances?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
